  function enterUser(){const c=hex2hsv(myColor);uh=c[0];us=c[1];uv=Math.max(.35,c[2]);uName.value=myName;paintUser()}
  function wheelPick(e){
    const r=uWheel.getBoundingClientRect(),R=r.width/2,dx=e.clientX-(r.left+R),dy=e.clientY-(r.top+R);
    setHSV(Math.atan2(dy,dx)*180/Math.PI,Math.min(Math.hypot(dx,dy),R)/R,uv);
  }
  uWheel.addEventListener('pointerdown',e=>{try{uWheel.setPointerCapture(e.pointerId)}catch(_){}wheeling=true;wheelPick(e)});
  uWheel.addEventListener('pointermove',e=>{if(wheeling)wheelPick(e)});
  uWheel.addEventListener('pointerup',()=>{wheeling=false});
